import re; from .rules import RULES; P = {"TRUNCATE": r"^\s*TRUNCATE\b", "DELETE_NO_WHERE": r"^\s*DELETE\s+FROM\b(?!.*\bWHERE\b)", "UPDATE_NO_WHERE": r"^\s*UPDATE\b(?!.*\bWHERE\b)", "ADD_NOT_NULL_NO_DEFAULT": r"\bADD\s+COLUMN\b(?!.*\bDEFAULT\b).*\bNOT\s+NULL\b", "ALTER_TYPE": r'\bALTER\s+(COLUMN\s+)?[\w".]+\s+(SET\s+DATA\s+)?TYPE\b', "CREATE_INDEX_BLOCKING": r"^\s*CREATE\s+(UNIQUE\s+)?INDEX(?!\s+CONCURRENTLY\b)\b"}; blank = lambda m: re.sub(r"[^\n]", " ", m.group(0)); clean = lambda sql: re.sub(r"--[^\n]*", blank, re.sub(r"/\*.*?\*/", blank, sql, flags=re.S)); scan = lambda sql: [(sql[:m.start(1)].count("\n") + 1, r[0], r[1], r[3]) for m in re.finditer(r"\s*([^;]+)", clean(sql)) if m.group(1).strip() for r in RULES if re.search(P.get(r[0], r[2]), m.group(1), re.I | re.S)]
